    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 100;
    padding: var(--spacing-sm) 0;
}

.header-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.logo span {
    color: var(--color-accent);
}

.nav-links {
    display: flex;
    gap: var(--spacing-md);
}

.nav-links a {
    font-size: 0.9rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.nav-links a:hover {
    color: var(--color-accent);
}

.header-actions {
    display: flex;
    gap: var(--spacing-sm);
    align-items: center;
}

.search-form {
    display: flex;
    align-items: center;
    background: var(--color-surface);
    border-radius: 20px;
    padding: 0 10px;
    border: 1px solid var(--color-border);
}

.search-input {
    background: none;
    border: none;
    color: var(--color-text);
    padding: 8px;
    width: 150px;
    font-size: 0.9rem;
    outline: none;
}

.icon-button {
    background: none;
    border: none;
    color: var(--color-text);
    cursor: pointer;
    padding: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    transition: var(--transition-base);
}

.icon-button:hover {
    background: var(--color-surface);
}

.cart-link {
    position: relative;
}

.cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background: var(--color-accent);
    color: var(--color-accent-text);
    font-size: 0.7rem;
    font-weight: bold;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero */
.hero {
    padding: var(--spacing-xl) 0;
    background: linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)), url('https://placehold.co/1920x1080/0a0a0a/333333?text=Hero+Image');
    background-size: cover;
    background-position: center;
    text-align: center;
}

.hero-title {
    font-size: 4rem;
    margin-bottom: var(--spacing-sm);
}

.hero-subtitle {
    font-size: 1.25rem;
    color: var(--color-text-muted);
    max-width: 600px;
    margin: 0 auto var(--spacing-lg);
}

.hero-actions {
    display: flex;
    justify-content: center;
    gap: var(--spacing-md);
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 12px 32px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    cursor: pointer;
    border: none;
    transition: var(--transition-base);
}

.btn-primary {
    background-color: var(--color-text);
    color: var(--color-bg);
}

.btn-primary:hover {
    background-color: var(--color-accent);
}

.btn-outline {
    background-color: transparent;
    border: 2px solid var(--color-text);
    color: var(--color-text);
}

.btn-outline:hover {
    background-color: var(--color-text);
    color: var(--color-bg);
}

.btn-accent {
    background-color: var(--color-accent);
    color: var(--color-accent-text);
}

/* Sections */
.section {
    padding: var(--spacing-xl) 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: var(--spacing-lg);
}

.view-all {
    text-decoration: underline;
    font-weight: 500;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-lg) var(--spacing-md);
}

.product-card {
    group: relative;
}

.product-image {
    position: relative;
    background-color: var(--color-surface);
    aspect-ratio: 3/4;
    overflow: hidden;
    margin-bottom: var(--spacing-sm);
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.btn-quick-add {
    position: absolute;
    bottom: -50px;
    left: 0;
    width: 100%;
    padding: 12px;
    background: var(--color-text);
    color: var(--color-bg);
    border: none;
    font-weight: 600;
    transition: var(--transition-base);
    opacity: 0;
}

.product-card:hover .btn-quick-add,
.product-card:focus-within .btn-quick-add {
    bottom: 0;
    opacity: 1;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-xs);
}

.price {
    color: var(--color-text-muted);
}

/* Deals */
.deals-banner {
    background: var(--color-surface);
    padding: var(--spacing-xl) var(--spacing-lg);
    border: 1px solid var(--color-border);
    text-align: center;
}

.deals-offer {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-lg);
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: var(--spacing-md);
}

.editorial-main {
    position: relative;
}

.editorial-main img {
    width: 100%;
    aspect-ratio: 2/1;
    object-fit: cover;
}

.editorial-main .editorial-content {
    background: var(--color-surface);
    padding: var(--spacing-lg);
    margin-top: calc(-1 * var(--spacing-lg));
    margin-left: var(--spacing-lg);
    position: relative;
    max-width: 500px;
}

.editorial-side {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.editorial-card {
    background: var(--color-surface);
}

.editorial-card img {
    width: 100%;
    aspect-ratio: 1/1;
    object-fit: cover;
}

.editorial-card h3, .editorial-card p {
    padding: 0 var(--spacing-sm);
}

.editorial-card h3 {
    margin-top: var(--spacing-sm);
}

/* Footer */
.site-footer {
    background: var(--color-surface);
    padding: var(--spacing-xl) 0 var(--spacing-md);
    border-top: 1px solid var(--color-border);
    margin-top: var(--spacing-xl);
}

.footer-grid {
    display: grid;
    grid-template-columns: 1.5fr 3fr 1.5fr;
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-xl);
}

.footer-nav {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
}

.footer-nav-col h3 {
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: var(--spacing-md);
}

.footer-nav-col ul li {
    margin-bottom: var(--spacing-sm);
}

.footer-nav-col a {
    color: var(--color-text-muted);
    font-size: 0.9rem;
}

.footer-nav-col a:hover {
    color: var(--color-text);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-xs);
    margin-top: var(--spacing-md);
}

.newsletter-form input {
    background: var(--color-bg);
    border: 1px solid var(--color-border);
    color: var(--color-text);
    padding: 10px;
    flex-grow: 1;
}

.footer-bottom {
    border-top: 1px solid var(--color-border);
    padding-top: var(--spacing-md);
    display: flex;
    justify-content: space-between;
    color: var(--color-text-muted);
    font-size: 0.8rem;
}

/* Accessibility & Focus */
:focus-visible {
    outline: 2px solid var(--color-focus);
    outline-offset: 4px;
}

@media (forced-colors: active) {
    .btn {
        border: 1px solid ButtonBorder;
    }
    .btn-quick-add {
        border: 1px solid ButtonBorder;
    }
}

/* Mobile Toggle */
.nav-toggle {
    display: none;
    background: none;
    border: none;
    padding: 10px;
    cursor: pointer;
    position: relative;
    width: 44px;
    height: 44px;
}

.hamburger, .hamburger::before, .hamburger::after {
    display: block;
    background: var(--color-text);
    height: 2px;
    width: 24px;
    transition: var(--transition-base);
}

.hamburger {
    position: absolute;
    top: 21px;
    left: 10px;
}

.hamburger::before, .hamburger::after {
    content: '';
    position: absolute;
    left: 0;
}

.hamburger::before { top: -8px; }
.hamburger::after { bottom: -8px; }

.nav-toggle[aria-expanded="true"] .hamburger {
    background: transparent;
}

.nav-toggle[aria-expanded="true"] .hamburger::before {
    transform: rotate(45deg);
    top: 0;
}

.nav-toggle[aria-expanded="true"] .hamburger::after {
    transform: rotate(-45deg);
    bottom: 0;
}

/* Responsive */
@media (max-width: 768px) {
    .nav-toggle {
        display: block;
        background: none;
        border: none;
        color: var(--color-text);
        padding: 10px;
        cursor: pointer;
    }

    .nav-links {
        display: none; /* Will be toggled by JS */
        position: absolute;
        top: 100%;
        left: 0;
        width: 100%;
        background: var(--color-bg);
        flex-direction: column;
        padding: var(--spacing-md);
        border-bottom: 1px solid var(--color-border);
    }

    .nav-links.is-active {
        display: flex;
    }

    .hero-title {
        font-size: 2.5rem;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .editorial-main .editorial-content {
        margin: 0;
        max-width: none;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .footer-nav {
        grid-template-columns: 1fr 1fr;
    }
}
