        document.addEventListener('DOMContentLoaded', () => {
            const navToggle = document.querySelector('.nav-toggle');
            const navMenu = document.querySelector('#nav-menu');

            if (navToggle && navMenu) {
                navToggle.addEventListener('click', () => {
                    const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
                    navToggle.setAttribute('aria-expanded', !isExpanded);
                    navMenu.classList.toggle('is-active');
                });
            }

            // Quick Add Button functionality
            const quickAddButtons = document.querySelectorAll('.btn-quick-add');
            const cartCount = document.querySelector('.cart-count');
            const cartLink = document.querySelector('.cart-link');
            const announcementRegion = document.getElementById('announcement-region');

            let count = 0;

            quickAddButtons.forEach(button => {
                button.addEventListener('click', () => {
                    count++;
                    const productName = button.closest('.product-card').querySelector('h3').textContent;

                    if (cartCount) {
                        cartCount.textContent = count;
                        cartLink.setAttribute('aria-label', `Shopping Cart, ${count} items`);

                        // Announce to Screen Readers
                        if (announcementRegion) {
                            announcementRegion.textContent = `Added ${productName} to cart. Total items: ${count}`;
                            // Clear after announcement to avoid stale info if re-added
                            setTimeout(() => {
                                announcementRegion.textContent = '';
                            }, 3000);
                        }
                    }
                });
            });

            // Newsletter Form Mock
            const newsletterForm = document.querySelector('.newsletter-form');
            const newsletterStatus = document.getElementById('newsletter-status');

            if (newsletterForm && newsletterStatus) {
                newsletterForm.addEventListener('submit', (e) => {
                    e.preventDefault();
                    newsletterStatus.classList.remove('sr-only');
                    newsletterStatus.textContent = 'Thank you for subscribing!';
                    newsletterForm.reset();

                    setTimeout(() => {
                        newsletterStatus.textContent = '';
                        newsletterStatus.classList.add('sr-only');
                    }, 5000);
                });
            }

            // Search Form Mock
            const searchForm = document.querySelector('.search-form');
            if (searchForm) {
                searchForm.addEventListener('submit', (e) => {
                    e.preventDefault();
                    const query = searchForm.querySelector('input').value;
                    if (announcementRegion) {
                        announcementRegion.textContent = `Searching for ${query}...`;
                    }
                });
            }
        });
    </script>
